def ingest_driver_ping(kafka_producer, city_id: str, driver_id: str, lat: float, lon: float, ts_ms: int):
    kafka_producer.send(
        topic='driver.location.pings',
        key=city_id.encode(),
        value={'driver_id': driver_id, 'lat': lat, 'lon': lon, 'ts_ms': ts_ms}
    )

def route_to_city_cluster(city_registry: dict, city_id: str) -> str:
    endpoint = city_registry.get(city_id)
    if not endpoint:
        raise KeyError(f'Unknown metro region: {city_id}')
    return endpoint

def match_batch_greedy_fallback(riders: list, drivers: list, eta_matrix: dict) -> list[tuple]:
    pairs = sorted(((eta_matrix[(r, d)], r, d) for r in riders for d in drivers), key=lambda x: x[0])
    used_r, used_d, matches = set(), set(), []
    for eta, r, d in pairs:
        if r not in used_r and d not in used_d:
            used_r.add(r); used_d.add(d); matches.append((r, d, eta))
    return matches

def try_acquire_driver_lease(redis, driver_id: str, trip_id: str, ttl_sec: int = 15) -> bool:
    return bool(redis.set(f'lock:driver:{driver_id}', trip_id, nx=True, ex=ttl_sec))

def release_driver_lease(redis, driver_id: str, trip_id: str) -> None:
    lua = "if redis.call('get', KEYS[1]) == ARGV[1] then return redis.call('del', KEYS[1]) else return 0 end"
    redis.eval(lua, 1, f'lock:driver:{driver_id}', trip_id)

def compute_smoothed_surge(cell_ratio: float, neighbor_ratios: list[float]) -> float:
    blended = 0.6 * cell_ratio + 0.4 * (sum(neighbor_ratios) / max(1, len(neighbor_ratios)))
    return round(min(4.0, max(1.0, 1.0 + 0.5 * max(0.0, blended - 1.2))), 1)
